    // 1. Parse the document using the engine
    parseDocument(file).then(words => {
        if (words.length === 0) {
            console.error("Parsing failed or returned empty text.");
            return;
        }

        // 2. Store the parsed words
        state.readingText = words;
        state.wordChunkIndex = 0;

        // 3. Transition to reader view (assuming switchView is implemented)
        switchView('reader');
        console.log(`Document loaded successfully. Total words: ${words.length}`);
    });
}

function startReading() {
    if (state.readingText.length === 0) {
        console.warn("No text loaded to read.");
        return;
    }
    if (state.isReading) return;

    state.isReading = true;
    console.log("Starting RSVP reading...");

    // Start the reading loop (using setInterval for simplicity)
    const intervalId = setInterval(() => {
        tick();
        if (state.wordChunkIndex >= state.readingText.length) {
            clearInterval(intervalId);
            state.isReading = false;
            console.log("Reading finished.");
        }
    }, calculateDelay(state.readingText[state.wordChunkIndex])); // Initial delay
}

function tick() {
    if (!state.isReading || state.wordChunkIndex >= state.readingText.length) return;

    // 1. Get the current word chunk (simplified: one word per chunk for now)
    const currentWord = state.readingText[state.wordChunkIndex];

    // 2. Update the visual display (Placeholder: In a real app, this updates the DOM)
    console.log(`Displaying chunk ${state.wordChunkIndex + 1}: ${currentWord}`);

    // 3. Advance the index
    state.wordChunkIndex++;

    // 4. Calculate and set the next delay (This is where chunking logic would refine the delay)
    // For now, we just rely on the interval set in startReading, but this is where dynamic timing happens.
}

