// app.js - Core Application Logic

/**
 * Global State Management
 * @type {object}
 */
const state = {
    currentView: 'dashboard',
    readingText: [],
    wordChunkIndex: 0,
    isReading: false,
    speedWPM: 300,
    theme: 'oled-dark'
};

// --- Initialization ---
document.addEventListener('DOMContentLoaded', () => {
    console.log("SpeedReader App Initializing...");
    // Load state from localStorage
    // Setup event listeners for UI elements
    // Initialize theme based on state.theme
});

// --- UI Handlers ---
function switchView(viewName) {
    // Logic to hide/show dashboard-view and reader-view
    state.currentView = viewName;
}

function handleFileDrop(file) {
    // 1. Parse the document using the engine
    parseDocument(file).then(words => {
        if (words.length === 0) {
            console.error("Parsing failed or returned empty text.");
            return;
        }

        // 2. Store the parsed words
        state.readingText = words;
        state.wordChunkIndex = 0;

        // 3. Transition to reader view (assuming switchView is implemented)
        switchView('reader');
        console.log(`Document loaded successfully. Total words: ${words.length}`);
    });
}

// --- Parsing Engine ---
async function parseDocument(file) {
    const extension = file.name.split('.').pop().toLowerCase();
    let text = '';

    try {
        if (extension === 'txt' || extension === 'md' || extension === 'rtf') {
            text = await file.text();
        } else if (extension === 'pdf') {
            const pdf = await pdfjsLib.getDocument({ data: await file.arrayBuffer() }).promise;
            for (let i = 1; i <= pdf.numPages; i++) {
                const page = await pdf.getPage(i);
                const textContent = await page.getTextContent();
                text += textContent.items.map(item => item.str).join(' ') + '\n';
            }
        } else if (extension === 'docx') {
            const result = await mammoth.convertToText({ arrayBuffer: await file.arrayBuffer() });
            text = result.value;
        } else if (extension === 'odt' || extension === 'epub') {
            const zip = await JSZip.loadAsync(await file.arrayBuffer());
            let content = '';
            if (extension === 'odt') {
                const xml = await zip.file('content.xml').async("string");
                const parser = new DOMParser();
                const doc = parser.parseFromString(xml, "text/xml");
                const paragraphs = doc.querySelectorAll('text:p');
                paragraphs.forEach(p => {
                    content += p.textContent + ' ';
                });
                text = content;
            } else if (extension === 'epub') {
                const files = zip.file(/.+\.(xhtml|html|xml)$/i);
                for (const file of files) {
                    const xml = await file.async("string");
                    const parser = new DOMParser();
                    const doc = parser.parseFromString(xml, "text/xml");
                    const textNode = doc.querySelector('body') || doc;
                    text += textNode.textContent + ' ';
                }
                text = content;
            }
        } else {
            throw new Error('Unsupported file type.');
        }

        const cleanedText = text.replace(/[\r\n]+/g, ' ').replace(/\s+/g, ' ').trim();
        return cleanedText.split(/\s+/).filter(w => w.length > 0);

    } catch (error) {
        console.error("Error parsing document:", error);
        alert("Failed to parse document. Check console for details.");
        return [];
    }
}

// --- RSVP Core Engine ---
function startReading() {
    if (state.readingText.length === 0) {
        console.warn("No text loaded to read.");
        return;
    }
    if (state.isReading) return;

    state.isReading = true;
    console.log("Starting RSVP reading...");

    // Start the reading loop (using setInterval for simplicity)
    const intervalId = setInterval(() => {
        tick();
        if (state.wordChunkIndex >= state.readingText.length) {
            clearInterval(intervalId);
            state.isReading = false;
            console.log("Reading finished.");
        }
    }, calculateDelay(state.readingText[state.wordChunkIndex])); // Initial delay
}

function tick() {
    if (!state.isReading || state.wordChunkIndex >= state.readingText.length) return;

    // 1. Get the current word chunk (simplified: one word per chunk for now)
    const currentWord = state.readingText[state.wordChunkIndex];

    // 2. Update the visual display (Placeholder: In a real app, this updates the DOM)
    console.log(`Displaying chunk ${state.wordChunkIndex + 1}: ${currentWord}`);

    // 3. Advance the index
    state.wordChunkIndex++;

    // 4. Calculate and set the next delay (This is where chunking logic would refine the delay)
}

// --- Utility Functions ---
function calculateDelay(chunk) {
    // Dynamic delay based on punctuation and word length
    return 1000 / state.speedWPM;
}

// Export functions if needed for modularity
window.SpeedReaderApp = {
    startReading,
    handleFileDrop,
    // ...
};
